import * as THREE from 'three/webgpu';
import { uv, smoothstep, min, sub, float } from 'three/tsl';
import gsap from 'gsap';
import * as primitives from '@/primitives';
import { createTextMesh } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {Array<string>} textContent
 */

/**
 * @typedef {Object} NodeContext
 * @property {Object} primitives - map of primitive functions
 * @property {Object} fontAtlas - MSDF font atlas utilities
 */

/**
 * Create the ticker ribbon node.
 *
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // Root group
  const root = new THREE.Group();
  root.position.set(0, 0, 0);
  root.scale.set(1, 1, 1);
  root.rotation.set(0, 0, 0);

  // ---------- Background Plane ----------
  const planeGeometry = new THREE.PlaneGeometry(7.0, 0.35);
  const bgMaterial = new THREE.MeshStandardNodeMaterial({
    transparent: true,
    depthWrite: true,
    depthTest: true,
  });

  // Base color
  bgMaterial.colorNode = new THREE.ColorNode(new THREE.Color('#111117'));
  bgMaterial.roughnessNode = float(0.6);
  bgMaterial.metalnessNode = float(0.2);

  // Edge‑fade mask (left 0‑0.09, right 0.91‑1)
  const uvNode = uv();
  const maskLeft = sub(1, smoothstep(float(0.0), float(0.09), uvNode.x));
  const maskRight = sub(1, smoothstep(float(0.91), float(1.0), uvNode.x));
  const opacityMask = min(maskLeft, maskRight);
  bgMaterial.alphaNode = opacityMask;

  const bgPlane = new THREE.Mesh(planeGeometry, bgMaterial);
  bgPlane.renderOrder = 0;
  root.add(bgPlane);

  // ---------- Scrolling Text ----------
  const scrollGroup = new THREE.Group();
  scrollGroup.renderOrder = 1;

  const gap = 0.5; // 2 × base unit (0.25)

  let cursor = 0;
  const textMeshes = [];

  // Helper to create a mesh for a single entry
  function addEntry(text) {
    const mesh = createTextMesh(text, {
      family: 'JetBrains Mono',
      fontSize: 13,
      fontWeight: 700,
      letterSpacing: 0.06,
      lineHeight: 1,
      color: '#e8ecf2',
      atlas: ctx.fontAtlas,
    });

    // Ensure geometry has bounding box
    if (!mesh.geometry.boundingBox) mesh.geometry.computeBoundingBox();
    const bbox = mesh.geometry.boundingBox;
    const width = bbox.max.x - bbox.min.x;

    // Position on baseline, raised slightly in Z for lighting
    mesh.position.set(cursor + width / 2, 0, 0.02);
    cursor += width + gap;

    scrollGroup.add(mesh);
    textMeshes.push({ mesh, width });
  }

  // Build the strip from config.textContent (array of strings)
  (config.textContent || []).forEach(addEntry);

  // Duplicate the strip for seamless looping
  const duplicateGroup = scrollGroup.clone(true);
  duplicateGroup.position.x = cursor;
  scrollGroup.add(duplicateGroup);
  cursor *= 2; // total length of the concatenated strip

  // Apply fly‑through primitive for constant leftward motion
  // The primitive expects the target object and its params.
  if (ctx.primitives && typeof ctx.primitives['fly-through'] === 'function') {
    ctx.primitives['fly-through'](scrollGroup, { depthUnits: 0, speed: 0.4 });
  }

  root.add(scrollGroup);

  // ---------- UserData ----------
  root.userData.handlers = {};

  // Store disposables for cleanup
  const disposables = [];

  // Cleanup function
  root.userData.cleanup = () => {
    // Kill any GSAP timelines (none created here but guard anyway)
    gsap.globalTimeline.clear();

    // Dispose meshes and geometries
    bgPlane.geometry.dispose();
    bgMaterial.dispose();

    textMeshes.forEach(({ mesh }) => {
      if (mesh.geometry) mesh.geometry.dispose();
      if (mesh.material) mesh.material.dispose();
    });

    // Dispose duplicated meshes (they share geometry/material with originals)
    // No extra disposal needed.

    // Dispose any additional disposables collected elsewhere
    disposables.forEach((d) => {
      if (typeof d.dispose === 'function') d.dispose();
    });
  };

  return root;
}
